def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a grid to represent the classroom
    grid = [[0] * N for _ in range(M)]

    # Add aisles to the grid
    for i in range(K):
        for j in range(L):
            grid[i][j] = 1

    # Count the number of chatting pairs that can be separated by adding an aisle
    pair_count = 0
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        if grid[x1][y1] and grid[x2][y2]:
            pair_count += 1

    # Select the most effective positions for aisles
    rows = [[] for _ in range(M)]
    cols = [[] for _ in range(N)]
    for i in range(M):
        for j in range(N):
            if grid[i][j] == 0:
                rows[i].append(j)
                cols[j].append(i)

    # Remove pairs that cannot be separated from the list
    for i in range(len(rows)):
        for j in range(len(cols)):
            if len(rows[i]) > 0 and len(cols[j]) > 0:
                rows[i] = [x for x in rows[i] if x != cols[j][0]]
                cols[j] = [x for x in cols[j] if x != rows[i][0]]

    # Return the optimal row and column indices for the aisles
    row_indices = [i for i in range(M) if len(rows[i]) > 0]
