def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, 0, -1):
        coeff = coeffs[i]
        if coeff != 0:
            term = ''
            if coeff < 0:
                term += '-'
            term += str(abs(coeff))
            if coeff != 1 or i != 1:
                term += 'x'
            if i > 1:
                term += '^' + str(i)
            terms.append(term)
    return '+'.join(terms)
